/td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n        <tr><td style=\"height:4px;line-height:4px;font-size:0;background:#E10600;\">&nbsp;</td></tr>\n        <tr>\n          <td class=\"px\" style=\"padding:36px 40px 30px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.6;color:#1b1b1b;\">\n<p style=\"margin:0 0 8px;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#E10600;\">Planning de la semaine</p>\n<h1 class=\"h1\" style=\"margin:0 0 18px;font-family:'Arial Black',Arial,Helvetica,sans-serif;font-size:30px;line-height:1.2;color:#0b0b0c;\">Votre semaine chez Meliora, {{firstName}}</h1>\n<p style=\"margin:0 0 14px;\">Voici les cours collectifs du {{weekLabel}}. Les places sont limitées : réservez depuis l’application.</p>\n{{{scheduleHtml}}}\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:28px 0 10px;\"><tr><td style=\"border-radius:8px;background:#E10600;\"><a href=\"{{appUrl}}\" style=\"display:inline-block;padding:14px 28px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:bold;color:#ffffff;text-decoration:none;border-radius:8px;\">Réserver mes cours</a></td></tr></table>\n          </td>\n        </tr>\n        <tr>\n          <td class=\"px\" style=\"background:#0b0b0c;padding:26px 32px;font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:1.7;color:#bdbdbd;\">\n            <strong style=\"color:#ffffff;font-size:13px;letter-spacing:1px;\">MELIORA GYM</strong><br>\n            {{address}}{{#if phone}} · {{phone}}{{/if}}<br>\n            <a href=\"{{instagramUrl}}\" style=\"color:#ffffff;text-decoration:underline;\">Instagram {{instagramHandle}}</a>\n            &nbsp;·&nbsp; <a href=\"{{mapsUrl}}\" style=\"color:#ffffff;text-decoration:underline;\">Itinéraire</a>\n            &nbsp;·&nbsp; <a href=\"{{websiteUrl}}\" style=\"color:#ffffff;text-decoration:underline;\">Site web</a>\n            {{#if footerNote}}<p style=\"margin:14px 0 0;color:#8c8c8c;\">{{footerNote}}</p>{{/if}}\n            <p style=\"margin:14px 0 0;color:#6f6f6f;\">© {{year}} Meliora Gym — Sousse, Tunisie</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>\n"};

